#include <vector>
#include <algorithm>

class Solution {
public:
    int minOperations(std::vector<int>& nums) {
        int max_v = *std::max_element(nums.begin(), nums.end());
        std::vector<int> spf(max_v + 1);
        for (int i = 0; i <= max_v; ++i) spf[i] = i;
        for (int i = 2; i * i <= max_v; ++i) {
            if (spf[i] == i) {
                for (int j = i * i; j <= max_v; j += i) {
                    if (spf[j] == j) spf[j] = i;
                }
            }
        }

        int ops = 0;
        int n = nums.size();
        for (int i = n - 2; i >= 0; --i) {
            if (nums[i] > nums[i + 1]) {
                int p = spf[nums[i]];
                if (p > nums[i + 1]) return -1;
                nums[i] = p;
                ops++;
            }
        }
        return ops;
    }
};

class Solution {
    public int minOperations(int[] nums) {
        int maxV = 0;
        for (int x : nums) maxV = Math.max(maxV, x);

        int[] spf = new int[maxV + 1];
        for (int i = 0; i <= maxV; i++) spf[i] = i;
        for (int i = 2; i * i <= maxV; i++) {
            if (spf[i] == i) {
                for (int j = i * i; j <= maxV; j += i) {
                    if (spf[j] == j) spf[j] = i;
                }
            }
        }

        int ops = 0;
        int n = nums.length;
        for (int i = n - 2; i >= 0; i--) {
            if (nums[i] > nums[i + 1]) {
                int p = spf[nums[i]];
                if (p > nums[i + 1]) return -1;
                nums[i] = p;
                ops++;
            }
        }
        return ops;
    }
}

var minOperations = function(nums) {
    let maxV = 0;
    for (const x of nums) if (x > maxV) maxV = x;

    const spf = new Int32Array(maxV + 1);
    for (let i = 0; i <= maxV; i++) spf[i] = i;
    for (let i = 2; i * i <= maxV; i++) {
        if (spf[i] === i) {
            for (let j = i * i; j <= maxV; j += i) {
                if (spf[j] === j) spf[j] = i;
            }
        }
    }

    let ops = 0;
